//! `<Name>ComponentView.generated.mm` (iOS ObjC++ Fabric view) emitter for `export_rn`.

use crate::writer::CodeWriter;

use crate::naming::{
    cpp_ident, escape_c_like_string, sanitize_single_line_comment, strip_on_prefix, to_pascal_case,
};
use crate::schema::export::{NveExportSpec, ObjectField, PropType};

pub(crate) fn emit_ios_component_view_mm(spec: &NveExportSpec) -> String {
    let name = &spec.name;
    let vtable_sym = spec.vtable_symbol();
    let mut out = CodeWriter::with_capacity(3072);

    writeln!(
        out,
        "// @generated by nve-codegen (`export_rn`) — backend: {}",
        spec.backend.as_str()
    );
    writeln!(
        out,
        "// iOS ObjC++ Fabric ComponentView subclassing `RCTNveComponentView`."
    );
    writeln!(out);
    writeln!(out, "#import \"RCTNveComponentView.h\"");
    writeln!(out, "#include \"{name}NveBridge.generated.hpp\"");
    writeln!(out);
    writeln!(out, "#if defined(NVE_WITH_RN_FABRIC) && NVE_WITH_RN_FABRIC");
    writeln!(out, "#import <React/RCTConversions.h>");
    writeln!(
        out,
        "#import <react/renderer/components/{name}/ComponentDescriptors.h>"
    );
    writeln!(
        out,
        "#import <react/renderer/components/{name}/EventEmitters.h>"
    );
    writeln!(
        out,
        "#import <react/renderer/components/{name}/Props.h>"
    );
    writeln!(
        out,
        "#import <react/renderer/components/{name}/RCTComponentViewHelpers.h>"
    );
    writeln!(out, "using namespace facebook::react;");
    writeln!(out, "#endif");
    writeln!(out);

    writeln!(out, "@interface {name}ComponentView : RCTNveComponentView");
    writeln!(out, "@end");
    writeln!(out);

    writeln!(out, "@implementation {name}ComponentView");
    writeln!(out);

    writeln!(out, "- (nullable NveGetInterfaceFn)defaultNveGetInterface {{");
    writeln!(out, "  return &{vtable_sym};");
    writeln!(out, "}}");
    writeln!(out);

    writeln!(out, "#if defined(NVE_WITH_RN_FABRIC) && NVE_WITH_RN_FABRIC");
    writeln!(out, "+ (ComponentDescriptorProvider)componentDescriptorProvider {{");
    writeln!(
        out,
        "  return concreteComponentDescriptorProvider<{name}ComponentDescriptor>();"
    );
    writeln!(out, "}}");
    writeln!(out);

    writeln!(
        out,
        "- (void)updateProps:(Props::Shared const &)props oldProps:(Props::Shared const &)oldProps {{"
    );
    writeln!(
        out,
        "  const auto &newViewProps = *std::static_pointer_cast<{name}Props const>(props);"
    );
    writeln!(
        out,
        "  NSMutableDictionary<NSString *, id> *dict = [NSMutableDictionary dictionary];"
    );
    for prop in &spec.props {
        let key = escape_c_like_string(&prop.name);
        let field = cpp_ident(&prop.name);
        match &prop.prop_type {
            PropType::Bool | PropType::Int32 | PropType::Float | PropType::Double => {
                writeln!(out, "  dict[@\"{key}\"] = @(newViewProps.{field});");
            }
            PropType::Color => {
                writeln!(
                    out,
                    "  if (newViewProps.{field}) {{\n    UIColor *uiColor = RCTUIColorFromSharedColor(newViewProps.{field});\n    if (uiColor) {{ dict[@\"{key}\"] = uiColor.description; }}\n  }}"
                );
            }
            PropType::StringEnum { .. } => {
                writeln!(
                    out,
                    "  dict[@\"{key}\"] = [NSString stringWithUTF8String:toString(newViewProps.{field}).c_str()];"
                );
            }
            PropType::String => {
                writeln!(
                    out,
                    "  dict[@\"{key}\"] = [NSString stringWithUTF8String:newViewProps.{field}.c_str()];"
                );
            }
            _ => {
                writeln!(
                    out,
                    "  // Prop `{}` forwarded via binary bridge",
                    sanitize_single_line_comment(&prop.name)
                );
            }
        }
    }
    writeln!(out, "  [self applyPropsDictionary:dict];");
    writeln!(out, "  [self drainNveEmittedEvents];");
    writeln!(out, "  [super updateProps:props oldProps:oldProps];");
    writeln!(out, "}}");
    writeln!(out, "#endif");
    writeln!(out);

    writeln!(
        out,
        "- (void)handleNveEvent:(NSString *)eventName payload:(NSDictionary<NSString *, id> *)payload {{"
    );
    writeln!(out, "#if defined(NVE_WITH_RN_FABRIC) && NVE_WITH_RN_FABRIC");
    writeln!(out, "  if (_eventEmitter != nullptr) {{");
    writeln!(
        out,
        "    auto emitter = std::static_pointer_cast<const {name}EventEmitter>(_eventEmitter);"
    );
    for (idx, ev) in spec.events.iter().enumerate() {
        let kw = if idx == 0 { "if" } else { "else if" };
        let short_name = strip_on_prefix(&ev.name);
        let ev_method = cpp_ident(&ev.name);
        let ev_struct_name = to_pascal_case(&ev.name);
        writeln!(
            out,
            "    {kw} ([eventName isEqualToString:@\"{}\"] || [eventName isEqualToString:@\"{}\"]) {{",
            escape_c_like_string(&ev.name),
            escape_c_like_string(&short_name)
        );
        writeln!(
            out,
            "      {name}EventEmitter::{ev_struct_name} eventPayload{{}};"
        );
        for f in &ev.payload {
            let fkey = escape_c_like_string(&f.name);
            let ffield = cpp_ident(&f.name);
            emit_objc_payload_field(&mut out, &fkey, &ffield, f);
        }
        writeln!(out, "      emitter->{ev_method}(std::move(eventPayload));");
        writeln!(out, "    }}");
    }
    writeln!(out, "  }}");
    writeln!(out, "#endif");
    writeln!(out, "  [super handleNveEvent:eventName payload:payload];");
    writeln!(out, "}}");
    writeln!(out);

    writeln!(out, "@end");
    writeln!(out);
    writeln!(out, "#if defined(NVE_WITH_RN_FABRIC) && NVE_WITH_RN_FABRIC");
    writeln!(out, "Class<RCTComponentViewProtocol> {name}Cls(void) {{");
    writeln!(out, "  return {name}ComponentView.class;");
    writeln!(out, "}}");
    writeln!(out, "#endif");

    out.into_string()
}

fn emit_objc_payload_field(out: &mut CodeWriter, key: &str, field: &str, f: &ObjectField) {
    match &f.field_type {
        PropType::Bool => {
            writeln!(
                out,
                "      if ([payload[@\"{key}\"] isKindOfClass:[NSNumber class]]) {{ eventPayload.{field} = [payload[@\"{key}\"] boolValue]; }}"
            );
        }
        PropType::Int32 | PropType::IntEnum { .. } => {
            writeln!(
                out,
                "      if ([payload[@\"{key}\"] isKindOfClass:[NSNumber class]]) {{ eventPayload.{field} = [payload[@\"{key}\"] intValue]; }}"
            );
        }
        PropType::Float => {
            writeln!(
                out,
                "      if ([payload[@\"{key}\"] isKindOfClass:[NSNumber class]]) {{ eventPayload.{field} = [payload[@\"{key}\"] floatValue]; }}"
            );
        }
        PropType::Double => {
            writeln!(
                out,
                "      if ([payload[@\"{key}\"] isKindOfClass:[NSNumber class]]) {{ eventPayload.{field} = [payload[@\"{key}\"] doubleValue]; }}"
            );
        }
        _ => {
            writeln!(
                out,
                "      if ([payload[@\"{key}\"] isKindOfClass:[NSString class]]) {{ eventPayload.{field} = [payload[@\"{key}\"] UTF8String]; }}"
            );
        }
    }
}
